/**
 * phrases.js  -  the fixed, non-model content and interface copy.
 *
 * Nothing here is ever generated by the model. That is deliberate: the calm
 * "verify with a number you look up yourself" guidance must be impossible for
 * a scammer (or a hijacked model) to suppress or rewrite.
 *
 * Spec ref: spec.md > Components > phrases.js
 * PRD ref:  prd.md > General scam phrases (always visible), prd.md > Phone-number guidance
 */

/** The always-visible awareness list. Same for everyone, on every message. */
