/** Fixed copy - the calm next step. Always shown with a result. Cannot be model output. */
export const NEXT_STEP_TEXT =
  'There is no rush, no matter what the message says. Do not reply, do not click, and do not send money or codes. ' +
  'If it mentions an account, a payment, or a refund, look up the company\'s number yourself - on their website, ' +
  'or the number on the back of your card - and call that one. You are allowed to take your time.';

/**
 * Independent-verification guidance. Shown when a message pushes a phone number
 * (spec.md > The Result Shape - never gated *only* on the model's boolean; app.js
 * also re-checks the raw text for number patterns, and that check requires an
 * actual number so this box does not appear on messages that do not mention one).
 */
export const PHONE_GUIDANCE_TEXT =
  'Some scams copy real logos, email addresses, and phone numbers perfectly. The only number you can trust is ' +
  'one you look up yourself - check the company\'s own website, your bank card, or your account statement, and ' +
  'call that number. Never call or message a number that came in the message itself.';

/** Error-state copy, mapped from the error codes in api.js. */
export const ERROR_COPY = {
  NO_KEY:
    'First Defense needs a key to reach the language model that does the reading. ' +
    'Nothing you paste is sent anywhere without one.',
  NETWORK:
    'The service that reads the message did not answer just now. This is usually a connection problem - ' +
    'please try again in a moment.',
  OFF_SHAPE:
    'The reading came back in a form this page could not use, so nothing is being shown. ' +
    'Rather than risk a confusing or wrong summary, we stop here.',
  EMPTY:
    'There was no message to look at. Paste the text you received, then try again.'
};

/**
 * The no-ask case. Stated plainly, with NO reassurance about the message itself.
 * Kept for compatibility; the live UI builds its own version of this copy.
 */
export const NO_ASK_TEXT =
  'This message does not clearly ask you to do anything - no money, no link, no details, no call. ' +
  'That does not make it safe or unsafe. If it still feels off, treat it the same way: do not reply, ' +
  'and verify with the company using a number you find yourself.';

/** The empty-tactics case. Again: no reassurance either way. */
export const NO_TACTICS_TEXT = 'This message does not lean on the usual pressure tactics. It can still be a scam.';

